81	  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount affects premium only)");
82	  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
83	  it.todo("sword policy, second claim of 1500 G after the first → payout 600 G, remainingCap 0 G");
